parts.text:
{
  "cases": [
    {
      "name": "replay reservation when available stock is below quantity",
      "family": "idempotency",
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"idem_stock\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":6},{\"op\":\"reserve\",\"tenant\":\"idem_stock\",\"key\":\"k2\",\"sku\":\"widget\",\"qty\":4},{\"op\":\"stock\",\"tenant\":\"idem_stock\",\"sku\":\"widget\"},{\"op\":\"reserve\",\"tenant\":\"idem_stock\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":6},{\"op\":\"stock\",\"tenant\":\"idem_stock\",\"sku\":\"widget\"},{\"op\":\"release\",\"tenant\":\"idem_stock\",\"key\":\"k1\"},{\"op\":\"stock\",\"tenant\":\"idem_stock\",\"sku\":\"widget\"},{\"op\":\"release\",\"tenant\":\"idem_stock\",\"key\":\"k2\"},{\"op\":\"stock\",\"tenant\":\"idem_stock\",\"sku\":\"widget\"}]"
    },
    {
      "name": "distinct tenants with identical key and payload maintain independent lifecycles",
      "family": "tenant_isolation",
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"cust-x\",\"key\":\"order-100\",\"sku\":\"widget\",\"qty\":3},{\"op\":\"reserve\",\"tenant\":\"cust-y\",\"key\":\"order-100\",\"sku\":\"widget\",\"qty\":3},{\"op\":\"release\",\"tenant\":\"cust-x\",\"key\":\"order-100\"},{\"op\":\"stock\",\"tenant\":\"cust-x\",\"sku\":\"widget\"},{\"op\":\"stock\",\"tenant\":\"cust-y\",\"sku\":\"widget\"},{\"op\":\"release\",\"tenant\":\"cust-y\",\"key\":\"order-100\"},{\"op\":\"stock\",\"tenant\":\"cust-y\",\"sku\":\"widget\"}]"
    },
    {
      "name": "sku case sensitivity and whitespace preservation",
      "family": "validation",
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"t_case\",\"key\":\"k1\",\"sku\":\"Widget\",\"qty\":2},{\"op\":\"reserve\",\"tenant\":\"t_case\",\"key\":\"k1\",\"sku\":\"SENSOR\",\"qty\":2},{\"op\":\"reserve\",\"tenant\":\"t_space\",\"key\":\"k_clean\",\"sku\":\"widget\",\"qty\":2},{\"op\":\"reserve\",\"tenant\":\" t_space \",\"key\":\"k_clean\",\"sku\":\"widget\",\"qty\":2},{\"op\":\"stock\",\"tenant\":\"t_space\",\"sku\":\"widget\"},{\"op\":\"stock\",\"tenant\":\" t_space \",\"sku\":\"widget\"}]"
    },
    {
      "name": "release and stock validation for non-string, empty, and boolean arguments",
      "family": "validation",
      "actions_json": "[{\"op\":\"release\",\"tenant\":\"\",\"key\":\"k1\"},{\"op\":\"release\",\"tenant\":\"val_args\",\"key\":\"\"},{\"op\":\"release\",\"tenant\":100,\"key\":\"k1\"},{\"op\":\"stock\",\"tenant\":\"\",\"sku\":\"widget\"},{\"op\":\"stock\",\"tenant\":true,\"sku\":\"widget\"},{\"op\":\"reserve\",\"tenant\":\"val_args\",\"key\":\"k1\",\"sku\":\"widget\",\"qty\":false},{\"op\":\"stock\",\"tenant\":\"val_args\",\"sku\":\"widget\"}]"
    },
    {
      "name": "release on unreserved or failed key returns not found",
      "family": "idempotency",
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"t_notfound\",\"key\":\"k_bad\",\"sku\":\"widget\",\"qty\":11},{\"op\":\"release\",\"tenant\":\"t_notfound\",\"key\":\"k_bad\"},{\"op\":\"reserve\",\"tenant\":\"t_notfound\",\"key\":\"k_fill\",\"sku\":\"widget\",\"qty\":10},{\"op\":\"reserve\",\"tenant\":\"t_notfound\",\"key\":\"k_insuf\",\"sku\":\"widget\",\"qty\":1},{\"op\":\"release\",\"tenant\":\"t_notfound\",\"key\":\"k_insuf\"},{\"op\":\"release\",\"tenant\":\"t_notfound\",\"key\":\"k_fill\"},{\"op\":\"stock\",\"tenant\":\"t_notfound\",\"sku\":\"widget\"}]"
    },
    {
      "name": "invalid payload on existing key returns invalid rather than conflict",
      "family": "payload_binding",
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"bind_t\",\"key\":\"key_b\",\"sku\":\"sensor\",\"qty\":4},{\"op\":\"reserve\",\"tenant\":\"bind_t\",\"key\":\"key_b\",\"sku\":\"invalid_sku\",\"qty\":4},{\"op\":\"reserve\",\"tenant\":\"bind_t\",\"key\":\"key_b\",\"sku\":\"sensor\",\"qty\":0},{\"op\":\"reserve\",\"tenant\":\"bind_t\",\"key\":\"key_b\",\"sku\":\"sensor\",\"qty\":12},{\"op\":\"reserve\",\"tenant\":\"bind_t\",\"key\":\"key_b\",\"sku\":\"widget\",\"qty\":5},{\"op\":\"reserve\",\"tenant\":\"bind_t\",\"key\":\"key_b\",\"sku\":\"sensor\",\"qty\":4},{\"op\":\"stock\",\"tenant\":\"bind_t\",\"sku\":\"sensor\"},{\"op\":\"stock\",\"tenant\":\"bind_t\",\"sku\":\"widget\"}]"
    },
    {
      "name": "delimiter collision resistance with colons and slashes across tenant and key",
      "family": "tenant_isolation",
      "actions_json": "[{\"op\":\"reserve\",\"tenant\":\"org/dept\",\"key\":\"item\",\"sku\":\"widget\",\"qty\":2},{\"op\":\"reserve\",\"tenant\":\"org\",\"key\":\"dept/item\",\"sku\":\"widget\",\"qty\":3},{\"op\":\"reserve\",\"tenant\":\"u:v\",\"key\":\"w\",\"sku\":\"sensor\",\"qty\":4},{\"op\":\"reserve\",\"tenant\":\"u\",\"key\":\"v:w\",\"sku\":\"sensor\",\"qty\":5},{\"op\":\"stock\",\"tenant\":\"org/dept\",\"sku\":\"widget\"},{\"op\":\"stock\",\"tenant\":\"org\",\"sku\":\"widget\"},{\"op\":\"stock\",\"tenant\":\"u:v\",\"sku\":\"sensor\"},{\"op\":\"stock\",\"tenant\":\"u\",\"sku\":\"sensor\"}]"
    }
  ],
  "rationale": "This batch systematically exercises untested contract clauses, execution orders, and partitions: (1) Idempotency evaluation order when current stock is zero or strictly less than qty, ensuring idempotency resolution precedes insufficient stock checks; (2) Multi-tenant reservation collision where two tenants use the exact same key with the same sku and qty, verifying independent tenant stores; (3) Validation order on existing reservation keys, verifying that invalid skus and quantities return 'invalid' before evaluating payload conflict; (4) Release behavior on keys that failed during validation or due to insufficient stock, verifying they return 'not_found' and never occupy the key; (5) Release and stock operations with empty string, boolean, or non-string tenant/key arguments, verifying immediate 'invalid' error before state lookup; (6) Case sensitivity for skus ('Widget', 'SENSOR') and whitespace preservation for tenants; and (7) Delimiter disambiguation for colon and slash composite identifiers."
}
